import React from 'react';
import AnalyticsPage from '../shared/AnalyticsPage';
import { useAuth } from '../../hooks/useAuth';

/**
 * components/creator/CreatorAnalytics.js - thin creator wrapper around
 * components/shared/AnalyticsPage; passes isAdmin=false + the signed-in
 * creator's profile id so the page self-scopes to that creator.
 *
 * A deliberate pass-through stub, not an unfinished component. @see docs/CODEBASE.md
 */
export default function CreatorAnalytics({ navigateToCampaign }) {
  const { profile } = useAuth();
  return <AnalyticsPage isAdmin={false} creatorProfileId={profile?.id} navigateToCampaign={navigateToCampaign} />;
}
