/**
 * components/shared/CreatorTaxSetAside.js: the creator's own tax set-aside line.
 *
 * Mounted at the foot of MyMoneyPage. One quiet sentence about the tax on this year's
 * earnings, expandable to the same working the admin Tax Center shows. Read-only: creators
 * never edit their return figures.
 *
 * The sentence changes VERB with the MONEY, not the calendar: contractor dollars are an
 * instruction to hold money that is not hers, a shortfall on wage dollars is only information,
 * and that second case is JUST THE FIGURE, no reason and no reassurance. @see docs/MONEY.md
 *
 * Deliberately year-to-date and calendar-year, ignoring MyMoneyPage's period
 * selector, because tax is annual. The copy says "this year" so the mismatch with
 * a month-filtered page above it reads as intentional rather than broken.
 *
 * @security every query here is RLS-scoped to the signed-in creator: own splits,
 *           own profile, own profile_tax_basis row. No admin path, no other
 *           person's figures, and nothing is written.
 * @gotcha this is the only creator-facing surface that names a tax liability.
 *         Keep the tone matter-of-fact: it is a planning number, not a warning.
 * @see utils/tax-estimate.js, components/shared/TaxEstimate.js (admin view)
 */
import React, { useCallback, useEffect, useState } from 'react';
import { supabase } from '../../lib/supabase';
import { fmtMoney } from '../../utils/format';
import { humanizeError } from '../../utils/errors';
import { estimatePersonTax, formatRate } from '../../utils/tax-estimate';
import { necBasis } from '../../utils/ledger-tax';
import { fetchCompBases } from '../../utils/compBasis';
import { PAYROLL_SPLIT_SELECT, sumTaxableComp, sumWithheld } from '../../utils/payroll';
import { ChevronIcon } from './Icon';
import Feedback from './Feedback';
import HelpIcon from './HelpIcon';

const log = (...args) => {
  if (process.env.NODE_ENV !== 'production') console.error('[CreatorTaxSetAside]', ...args);
};

/**
 * This creator's cleared destination splits for one calendar year, unsummed: the caller needs
 * both the whole year and the 1099 slice of it, and one date decides which side each falls on.
 *
 * @gotcha throws on a refusal rather than returning []. Zero cleared splits is a
 *         real answer here (nothing paid out yet) and a refused read is not, and
 *         the two produce the same panel if they share a return value.
 */
async function fetchClearedForYear(profileId, year) {
  const { data, error } = await supabase
    .from('payout_splits')
    .select(PAYROLL_SPLIT_SELECT)
    .gte('cleared_date', `${year}-01-01`).lte('cleared_date', `${year}-12-31`)
    .not('destination_id', 'is', null);
  if (error) throw error;
  return (data || []).filter((s) => s.payout?.profile_id === profileId);
}

/**
 * @param {string} props.profileId - the signed-in creator.
 * @param {boolean} [props.isMobile]
 */
export default function CreatorTaxSetAside({ profileId, isMobile = false }) {
  const taxYear = new Date().getFullYear();
  const [estimate, setEstimate] = useState(null);
  const [loadErr, setLoadErr] = useState(null);
  const [open, setOpen] = useState(false);

  const load = useCallback(async () => {
    if (!profileId) return;
    setLoadErr(null);

    try {
      const [profRes, basisRes, splits, compRes] = await Promise.all([
        supabase.from('profiles').select('date_of_birth').eq('id', profileId).maybeSingle(),
        supabase.from('profile_tax_basis')
          .select('tax_year, filing_status, agi, wages')
          .eq('profile_id', profileId)
          .order('tax_year', { ascending: false })
          .limit(1).maybeSingle(),
        fetchClearedForYear(profileId, taxYear),
        fetchCompBases(supabase),
      ]);
      // Both of these must gate the render, not just the log. No basis row means
      // single, no wages and no outside income, and no birthday means not a
      // dependent, which are the answers for a creator with nothing on file. A
      // refused read is not that creator, and the difference is a bracket.
      if (profRes.error) throw profRes.error;
      if (basisRes.error) throw basisRes.error;
      // Same rule as the two above: an unknown classification would read as contractor and
      // charge her self-employment tax her employer already withholds.
      if (compRes.error) throw compRes.error;

      const basis = basisRes.data || null;
      // sumTaxableComp, not a raw sum: money paid back for something she fronted
      // is her own money returning, not earnings, and must not be taxed again. It is also
      // what she EARNED rather than what landed, since Gusto splits the net check.
      const income = sumTaxableComp(splits);
      const nec = necBasis(splits, compRes.data, profileId);
      const basisIncome = basis && basis.tax_year !== taxYear
        ? sumTaxableComp(await fetchClearedForYear(profileId, basis.tax_year))
        : income;

      setEstimate(estimatePersonTax({
        taxYear,
        nysterysIncome: income,
        // The contractor slice of the year, which is the only part carrying self-employment
        // tax, and the tax payroll already took off the rest. Both come out of the SAME
        // splits as the income, so a paycheck cannot land its wages in one year and its
        // withholding in another.
        selfEmploymentIncome: nec,
        withheld: sumWithheld(splits),
        dateOfBirth: profRes.data?.date_of_birth || null,
        basis,
        basisNysterysIncome: basisIncome,
      }));
    } catch (err) {
      log('load', err);
      setEstimate(null);
      setLoadErr(humanizeError(err));
    }
  }, [profileId, taxYear]);

  useEffect(() => { load(); }, [load]);

  const frame = { marginTop: isMobile ? 22 : 28, paddingTop: 18, borderTop: '1px solid var(--border)' };

  // Error before Data, and in the panel's own slot: a creator who saw a figure
  // last month must not read a missing line as "nothing owed this year".
  if (loadErr) {
    return (
      <div style={frame}>
        <Feedback value={loadErr} />
        <button className="btn btn-secondary btn-sm" style={{ marginTop: 12 }} onClick={load}>
          Try again
        </button>
      </div>
    );
  }

  if (!estimate) return null;
  const e = estimate;
  // Contractor dollars are the ones she has to hold back herself, and they are also the only
  // ones carrying self-employment tax. Wage dollars had tax taken out already, however much.
  const hasContractorPay = e.selfEmploymentIncome > 0;
  const onPayroll = e.wageIncome > 0;
  // Nothing earned yet: say nothing rather than show a zero. A contractor who owes nothing gets
  // no line either, since the line's whole job is the instruction. On payroll "nothing left"
  // still needs saying: silence would read as a broken panel to someone who saw a figure last
  // year, and it is the reassuring half of the same sentence.
  if (e.nysterysIncome <= 0) return null;
  if (!onPayroll && e.setAside <= 0) return null;

  const lines = [['Earned so far this year', fmtMoney(e.nysterysIncome)]];
  if (hasContractorPay) lines.push(['Self-employment tax', fmtMoney(e.seTax)]);
  lines.push([
    `${hasContractorPay ? 'Income tax on the rest' : 'Federal income tax'}, `
      + `at ${formatRate(e.marginalRate)}`,
    fmtMoney(e.incomeTax),
  ]);
  // The real figure, never the income tax standing in for it. Reading them as equal is what
  // told her payroll had covered a year it had not: January to July was entered as historical
  // payroll with nothing taken out at all.
  if (onPayroll) lines.push(['Taken out of your pay', fmtMoney(e.withheld)]);
  lines.push([hasContractorPay ? 'Set aside' : 'Left to pay', fmtMoney(e.setAside)]);

  const headline = e.setAside <= 0
    ? 'Nothing to set aside for taxes.'
    : hasContractorPay
      ? `Set aside about ${fmtMoney(e.setAside)} for taxes.`
      : `About ${fmtMoney(e.setAside)} of tax on this year's pay has not been taken out.`;

  return (
    <div style={frame}>
      <button
        className="tax-est-working-toggle"
        style={{ marginTop: 0 }}
        aria-expanded={open}
        onClick={() => setOpen((o) => !o)}
      >
        <ChevronIcon size={11} style={{ transform: open ? 'rotate(90deg)' : 'none', transition: 'transform .25s ease' }} />
        <span>Tax on this</span>
      </button>

      <div style={{ marginTop: 8 }}>
        <span style={{ color: 'var(--white)', fontWeight: 500 }}>{headline}</span>
        {/* audience is required here: HelpIcon defaults to 'admin' and this
            component is creator-only, so the default dispatched an event the
            creator dashboard drops. */}
        <HelpIcon slug="tax-set-aside" audience="creator" />
        <div style={{ fontSize: 12, color: 'var(--muted)', marginTop: 3, maxWidth: 460, lineHeight: 1.45 }}>
          {hasContractorPay
            ? `Nobody withholds tax from this money, so a slice of ${fmtMoney(e.selfEmploymentIncome)}
               earned this year belongs to the IRS. Federal only, and an estimate.`
            : e.setAside > 0
              // Just the figure. Explaining the gap would be explaining the family's tax
              // affairs to a teenager who has not been asked to do anything about them.
              ? 'Federal only, and an estimate.'
              : `You are on payroll now, so tax comes out of each payment before it reaches you.
                 What lands in your account is yours to keep. Federal only, and an estimate.`}
        </div>
      </div>

      <div className="tax-est-working" data-open={open ? 'true' : 'false'}>
        <div className="tax-est-working-inner">
          <dl className="tax-est-calc" style={{ marginTop: 12 }}>
            {lines.map(([label, value], i) => (
              <div key={label} className="tax-est-calc-line" data-emphasis={i === lines.length - 1 ? 'true' : 'false'}>
                <dt>{label}</dt>
                <dd>{value}</dd>
              </div>
            ))}
          </dl>
          {e.isDependent && (
            <p className="tax-est-note">
              You are still a dependent this year, which makes your tax-free allowance smaller.
              {hasContractorPay ? ' Self-employment tax applies either way.' : ''}
            </p>
          )}
        </div>
      </div>
    </div>
  );
}
