import React from 'react';
import { useAuth } from '../../hooks/useAuth';
import OverviewPage from '../shared/OverviewPage';

/**
 * components/creator/CreatorOverview.js - thin creator wrapper around
 * components/shared/OverviewPage; passes isAdmin=false, the creator's profile id
 * and display name, plus navigation callbacks and a refreshKey.
 *
 * A deliberate pass-through stub, not an unfinished component. @see docs/CODEBASE.md
 */
export default function CreatorOverview({ setActiveView, navigateToCampaign, navigateToDeliverable, refreshKey }) {
  const { profile } = useAuth();
  return (
    <OverviewPage
      isAdmin={false}
      profileId={profile?.id}
      creatorName={profile?.creator_name || profile?.full_name}
      setActiveView={setActiveView}
      navigateToCampaign={navigateToCampaign}
      navigateToDeliverable={navigateToDeliverable}
      refreshKey={refreshKey}
    />
  );
}
