import React from 'react';
import PaymentsPage from '../shared/PaymentsPage';
import { useAuth } from '../../hooks/useAuth';

/**
 * components/creator/CreatorPayments.js - thin creator wrapper around
 * components/shared/PaymentsPage; passes isAdmin=false + the creator's profile id.
 *
 * A deliberate pass-through stub, not an unfinished component. @see docs/CODEBASE.md
 */
export default function CreatorPayments() {
  const { profile } = useAuth();
  return <PaymentsPage isAdmin={false} creatorProfileId={profile?.id} />;
}
