import React from 'react';
import MyMoneyPage from '../shared/MyMoneyPage';
import { useAuth } from '../../hooks/useAuth';

/**
 * components/creator/CreatorMyMoney.js - thin creator wrapper around
 * components/shared/MyMoneyPage; passes the creator's profile id. MyMoneyPage is
 * creator-only (no isAdmin prop); RLS auto-filters the ledger to owned accounts.
 *
 * A deliberate pass-through stub, not an unfinished component. @see docs/CODEBASE.md
 */
export default function CreatorMyMoney() {
  const { profile } = useAuth();
  return <MyMoneyPage profileId={profile?.id} />;
}
