import React from 'react';
import HelpView from '../shared/HelpView';

/**
 * components/creator/CreatorHelp.js - thin creator wrapper around
 * components/shared/HelpView; passes audience="creator" so only creator-facing
 * articles render, plus the deep-link slug and back-navigation props.
 *
 * A deliberate pass-through stub, not an unfinished component. @see docs/CODEBASE.md
 */
export default function CreatorHelp({ initialSlug = null, returnView = null, onBack }) {
  return <HelpView audience="creator" initialSlug={initialSlug} returnView={returnView} onBack={onBack} />;
}
