import { useAuth } from '../../hooks/useAuth';
import CampaignsPage from '../shared/CampaignsPage';

/**
 * components/creator/CreatorCampaigns.js - thin creator wrapper around
 * components/shared/CampaignsPage; passes isAdmin=false + the creator's profile
 * id, plus pending campaign/deliverable navigation targets and a status-change
 * callback.
 *
 * A deliberate pass-through stub, not an unfinished component. @see docs/CODEBASE.md
 *
 * @gotcha The creator Campaigns view stays MOUNTED (display:block/none) in
 *         CreatorDashboard to preserve panel state, unlike the other creator
 *         views which conditionally render. Logic for that lives in the parent,
 *         not here.
 */
export default function CreatorCampaigns({ pendingCampaignId, pendingDeliverableId, onCampaignStatusChanged }) {
  const { profile } = useAuth();
  return (
    <CampaignsPage
      isAdmin={false}
      profileId={profile?.id}
      pendingCampaignId={pendingCampaignId}
      pendingDeliverableId={pendingDeliverableId}
      onCampaignStatusChanged={onCampaignStatusChanged}
    />
  );
}
