/**
 * components/shared/MyMoneyPage.js. The creator's read-only money view, in no jargon.
 *
 * ONE honest hero number that is the EXACT sum of the buckets it splits across (landed, held,
 * on its way, gear, shared tools, tax, waiting, fees, in-kind), never an independently derived
 * gross, so it ties to the penny. Fees come from each invoice's processing_fee and the tax from
 * the paycheck, never a residual plug. Every source is RLS-scoped to the signed-in creator.
 *
 * @invariant the hero renders `recon.total`, which is the sum of the rendered buckets, so it
 *            cannot diverge from them.
 * @gotcha the OOP cycle is EXCLUDED from the buckets, because it is the creator's own fronted
 *         cash returning rather than earnings. It is surfaced as "Coming back to you".
 * @gotcha reversed JE pairs must drop BOTH halves or every total double-counts;
 *         isReversalEntry catches the reversal half.
 * @see docs/MONEY.md (creator My Money model, Pattern P)
 */
import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { supabase } from '../../lib/supabase';
import { PAYOUT_SPLIT_DESTINATION_EMBED } from '../../utils/queries';
import { fmtDate, fmtMonth, fmtMoney, extractMonths, round2 } from '../../utils/format';
import { invoiceFees } from '../../utils/invoiceMath';
import { campaignLabelParts, rewardLabel } from '../../utils/campaignLabel';
import { inPeriod, PeriodSelect } from '../../utils/period';
import HelpIcon from './HelpIcon';
import Feedback from './Feedback';
import { humanizeError } from '../../utils/errors';
import { ChevronIcon } from './Icon';
import { fetchCreatorOutstanding } from '../../utils/oopPayments';
import { isReversalEntry } from '../../utils/journalEntry';
import { sumWithheld } from '../../utils/payroll';
import CreatorTaxSetAside from './CreatorTaxSetAside';
import EmptyState from './EmptyState';

// Reconciliation palette - one warm hue, stepping down in lightness/chroma
// (dark-mode appropriate). Orange is the win and is spent only on it.
const SEG = {
  landed:  'var(--orange)',
  held:    'oklch(0.76 0.115 64)',
  onway:   'oklch(0.69 0.095 58)',
  gear:    'oklch(0.62 0.072 54)',
  tax:     'oklch(0.585 0.062 53)',
  waiting: 'oklch(0.55 0.052 52)',
  fees:    'oklch(0.48 0.020 56)',
};
// Non-cash gets a hatch, not a fill - silently reads as "not real money."
const INKIND_HATCH =
  'repeating-linear-gradient(135deg, rgba(255,140,66,0.22) 0 5px, rgba(255,140,66,0.04) 5px 11px)';

const prefersReduced =
  typeof window !== 'undefined' &&
  window.matchMedia &&
  window.matchMedia('(prefers-reduced-motion: reduce)').matches;

/**
 * My Money page. @see file header for the reconciliation model + invariants.
 * @param {string} props.profileId - the signed-in creator's uuid.
 */
export default function MyMoneyPage({ profileId }) {
  const [loadErr, setLoadErr] = useState(null);
  const [loading, setLoading] = useState(true);
  const [accounts, setAccounts] = useState([]);
  const [lines, setLines] = useState([]);
  const [invoices, setInvoices] = useState([]);
  const [splits, setSplits] = useState([]);
  const [destMeta, setDestMeta] = useState({}); // account_id -> { deferred, oop }
  const [oopOutstanding, setOopOutstanding] = useState(0);
  // All time. What Kym opens this page to read is what she is owed and what has landed, and
  // neither is a fact about one month. @see components/shared/PaymentsPage.js, utils/period.js
  const [period, setPeriod] = useState('all');
  const [isMobile, setIsMobile] = useState(() => window.innerWidth <= 768);
  const [openKey, setOpenKey] = useState(null);     // expanded bucket
  const [mounted, setMounted] = useState(prefersReduced);
  const [earningsOpen, setEarningsOpen] = useState(false);
  const [historyOpen, setHistoryOpen] = useState(false);

  useEffect(() => {
    const mq = window.matchMedia('(max-width: 768px)');
    const handler = e => setIsMobile(e.matches);
    mq.addEventListener('change', handler);
    return () => mq.removeEventListener('change', handler);
  }, []);

  const fetchAll = useCallback(async () => {
    if (!profileId) return;
    setLoading(true);
    setLoadErr(null);
    // Every figure here comes from the reads below. One falling through `|| []` into a
    // bucket of zero tells a creator she made $0.00.
    const { data: acctData, error: acctErr } = await supabase
      .from('ledger_accounts')
      .select('id, code, name, type, normal_balance, source_type, source_id, profile_id');
    if (acctErr) { setLoadErr(humanizeError(acctErr)); setLoading(false); return; }
    const accts = acctData || [];

    let lineData = [];
    if (accts.length > 0) {
      const acctIds = accts.map(a => a.id);
      const { data: ld, error: ldErr } = await supabase
        .from('ledger_entry_lines')
        .select('id, account_id, debit, credit, journal_entry:ledger_journal_entries(id, entry_date, description, source_type, source_id, reversed_by_je_id, is_posted)')
        .in('account_id', acctIds);
      if (ldErr) { setLoadErr(humanizeError(ldErr)); setLoading(false); return; }
      // Drop both halves of a reversed pair (original + counter-entry);
      // keeping only one double-counts every total.
      lineData = (ld || []).filter(l =>
        l.journal_entry
        && l.journal_entry.is_posted
        && !l.journal_entry.reversed_by_je_id
        && !isReversalEntry(l.journal_entry));
    }

    const { data: invData, error: invErr } = await supabase
      .from('invoices')
      .select('id, invoice_number, you_received, is_in_kind, processing_fee, discount_amount, campaign_id, reward_entry_id, campaign:campaigns(campaign_name, display_name, brand_name), reward_entry:platform_reward_entries(period_month, program:platform_rewards_programs(name))');
    if (invErr) { setLoadErr(humanizeError(invErr)); setLoading(false); return; }

    // payout_splits has TWO FKs to payment_destinations (destination_id and
    // reimbursement_destination_id, the latter added for OOP netting). The
    // embed MUST name the FK or PostgREST returns PGRST201 and the whole
    // query fails - which silently emptied `splits` and zeroed the gear
    // bucket. Validated against the live REST API.
    const { data: splitData, error: splitErr } = await supabase
      .from('payout_splits')
      .select(`id, amount, cleared_date, destination_id, expense_id, expense_period, recharge_allocation_id, notes, payout:creator_payouts(id, profile_id, withholding_amount, campaign:campaigns(campaign_name, display_name, brand_name), reward_entry:platform_reward_entries(period_month, program:platform_rewards_programs(name))), ${PAYOUT_SPLIT_DESTINATION_EMBED}(name, account_last4), expense:expenses(name)`);
    // Was a dev-only console.error, so in production this silently dumped
    // "Spent on your gear" into the fees residual: the incident above.
    if (splitErr) { setLoadErr(humanizeError(splitErr)); setLoading(false); return; }

    // fetchCreatorOutstanding throws rather than answering 0, because 0 is also
    // what "square with the company" looks like. Bound here so a refusal reports
    // instead of taking a reimbursement off her own money screen.
    let destRes;
    let outstanding;
    try {
      [destRes, outstanding] = await Promise.all([
        supabase.from('payment_destinations').select('id, is_deferred, oop_creator_id'),
        fetchCreatorOutstanding(profileId),
      ]);
    } catch (oopErr) { setLoadErr(humanizeError(oopErr)); setLoading(false); return; }
    const { data: destData, error: destErr } = destRes;
    // destMeta sorts deferred from landed; a failed read moves money between them.
    if (destErr) { setLoadErr(humanizeError(destErr)); setLoading(false); return; }
    const destById = new Map((destData || []).map(d => [d.id, d]));
    const meta = {};
    for (const a of accts) {
      if (a.source_type === 'destination') {
        const d = destById.get(a.source_id);
        if (d) meta[a.id] = { deferred: !!d.is_deferred, oop: d.oop_creator_id != null };
      }
    }

    setAccounts(accts);
    setLines(lineData);
    setInvoices(invData || []);
    // RLS already restricts payout_splits to this creator's own payouts.
    // Do NOT drop a row just because the (heavily nested) payout embed came
    // back null - that silently lost every expense split, dumping "Spent on
    // your gear" into the fees residual. Keep the profile guard
    // only as a no-op when the embed *is* present.
    setSplits((splitData || []).filter(s => !s.payout || s.payout.profile_id === profileId));
    setDestMeta(meta);
    setOopOutstanding(outstanding || 0);
    setLoading(false);
  }, [profileId]);

  useEffect(() => { fetchAll(); }, [fetchAll]);

  // One orchestrated entrance after data is ready.
  useEffect(() => {
    if (loading || prefersReduced) return;
    setMounted(false);
    const id = requestAnimationFrame(() => requestAnimationFrame(() => setMounted(true)));
    return () => cancelAnimationFrame(id);
  }, [loading, period]);

  const accountById = useMemo(() => {
    const m = new Map();
    accounts.forEach(a => m.set(a.id, a));
    return m;
  }, [accounts]);

  const isRevenueCampaign = a => a && /^401/.test(a.code);
  const isRevenueReward   = a => a && /^411/.test(a.code);
  const isInKindExp       = a => a && /^521/.test(a.code);
  const isPayable21xx     = a => a && /^21/.test(a.code);

  const periodLines = useMemo(
    () => lines.filter(l => inPeriod(l.journal_entry.entry_date, period)),
    [lines, period]
  );

  /**
   * Earnings events: one row per in-period 401x/411x revenue credit, labeled by
   * its invoice (brand+month or reward program) and flagged received vs waiting.
   * Feeds the "waiting on a brand" bucket and the "Every earning" list.
   * @gotcha in-kind invoices are skipped here (counted in their own bucket via
   *         521x debits), so they never appear as cash earnings.
   */
  const earnings = useMemo(() => {
    const invById = new Map(invoices.map(i => [i.id, i]));
    const out = [];
    for (const l of periodLines) {
      const a = accountById.get(l.account_id);
      if (!a) continue;
      const isCampaignCredit = isRevenueCampaign(a) && Number(l.credit || 0) > 0;
      const isRewardCredit   = isRevenueReward(a)   && Number(l.credit || 0) > 0;
      if (!isCampaignCredit && !isRewardCredit) continue;

      const je = l.journal_entry;
      const inv = (je.source_type === 'invoice') ? invById.get(je.source_id) : null;
      let label, received = true;
      if (inv) {
        if (inv.is_in_kind) continue;
        received = !!inv.you_received;
        if (inv.campaign?.brand_name) {
          const { month } = campaignLabelParts(inv.campaign);
          label = month ? `${inv.campaign.brand_name} · ${month}` : inv.campaign.brand_name;
        } else if (inv.reward_entry?.program?.name) {
          const ym = (inv.reward_entry.period_month || '').slice(0, 7);
          label = `${inv.reward_entry.program.name}${ym ? ' — ' + fmtMonth(ym) : ''}`;
        } else {
          label = inv.invoice_number || je.description || '';
        }
      } else if (isRewardCredit) {
        label = je.description || '';
      } else {
        label = je.description || '';
      }
      out.push({ key: `${je.id}:${l.id}`, date: je.entry_date, label, amount: Number(l.credit || 0), received, invId: inv ? inv.id : null });
    }
    out.sort((a, b) => (b.date || '').localeCompare(a.date || ''));
    return out;
  }, [periodLines, accountById, invoices]);

  function sourceLabel(payout) {
    if (!payout) return null;
    if (payout.campaign?.brand_name) {
      const { month } = campaignLabelParts(payout.campaign);
      return month ? `${payout.campaign.brand_name} · ${month}` : payout.campaign.brand_name;
    }
    return rewardLabel(payout.reward_entry) || null;
  }
  function shortDest(name) {
    if (!name) return 'your account';
    return name.replace(/^Payable\s*·\s*[^-]+-\s*/, '').replace(/\s*\(deferred payout\)\s*/i, '');
  }

  /**
   * Payment history: in-period cash clearances (21xx debits), in-kind product
   * (521x debits), and cleared expense/gear splits. Feeds the "landed" / "gear" /
   * "inkind" bucket detail and the "Every payment" list.
   */
  const history = useMemo(() => {
    const invById = new Map(invoices.map(i => [i.id, i]));
    const splitById = new Map(splits.map(s => [s.id, s]));
    const out = [];
    for (const l of periodLines) {
      const a = accountById.get(l.account_id);
      if (!a) continue;
      if (isPayable21xx(a) && Number(l.debit || 0) > 0) {
        const je = l.journal_entry;
        const sp = (je.source_type === 'split') ? splitById.get(je.source_id) : null;
        out.push({ key: `dest:${l.id}`, date: je.entry_date, source: sp ? sourceLabel(sp.payout) : null, dest: shortDest(a.name), amount: Number(l.debit || 0), variant: 'cash' });
      }
      if (isInKindExp(a) && Number(l.debit || 0) > 0) {
        const je = l.journal_entry;
        const inv = (je.source_type === 'invoice') ? invById.get(je.source_id) : null;
        const cname = inv?.campaign?.brand_name || inv?.invoice_number || 'a brand';
        out.push({ key: `ink:${l.id}`, date: je.entry_date, source: cname, amount: Number(l.debit || 0), variant: 'inkind' });
      }
    }
    for (const s of splits) {
      if (!s.cleared_date) continue;
      if (!inPeriod(s.cleared_date, period)) continue;
      if (s.expense_id) {
        out.push({ key: `exp:${s.id}`, date: s.cleared_date, source: sourceLabel(s.payout), expense: s.expense?.name || 'a business cost', amount: Number(s.amount || 0), variant: 'expense' });
      } else if (s.recharge_allocation_id) {
        out.push({ key: `rch:${s.id}`, date: s.cleared_date, source: sourceLabel(s.payout), expense: (s.notes || '').replace(/^Recharge:\s*/, '') || 'a shared tool', amount: Number(s.amount || 0), variant: 'recharge' });
      }
    }
    out.sort((a, b) => (b.date || '').localeCompare(a.date || ''));
    return out;
  }, [periodLines, accountById, splits, period, invoices]);

  /**
   * The reconciliation: every dollar earned this period, split across the buckets.
   * Returns { total, landed, held, onway, gear, recharge, waiting, fees, inKind }
   * where total is the exact sum of the rest (the hero). See the inline notes for
   * the OOP skip, the fees-from-source rule, and the residual handling.
   * @invariant total === landedAdj + held + onway + gear + recharge + waiting + fees + inKind.
   * @see docs/MONEY.md (creator My Money model).
   */
  const recon = useMemo(() => {
    let gross = 0, landed = 0, inKind = 0;
    const netByAcct = new Map(); // 21xx account_id -> credit - debit
    for (const l of periodLines) {
      const a = accountById.get(l.account_id);
      if (!a) continue;
      if (isRevenueCampaign(a) || isRevenueReward(a)) gross += Number(l.credit || 0);
      if (isInKindExp(a)) { gross += Number(l.debit || 0); inKind += Number(l.debit || 0); }
      if (isPayable21xx(a)) {
        // OOP reimbursement is its own cycle (her own fronted cash coming
        // back) - never a bucket. The held/on-its-way loop already skips it
        // via m.oop; the landed accumulation must skip it at the SAME point,
        // or its clearing debits leak into "Landed in your accounts".
        if ((destMeta[l.account_id] || {}).oop) continue;
        landed += Number(l.debit || 0);
        netByAcct.set(l.account_id, (netByAcct.get(l.account_id) || 0) + Number(l.credit || 0) - Number(l.debit || 0));
      }
    }
    let held = 0, onway0 = 0;
    for (const [acctId, net] of netByAcct) {
      if (net <= 0) continue;
      const m = destMeta[acctId] || {};
      if (m.oop) continue;          // her own fronted cash, a separate cycle
      if (m.deferred) held += net;  // "held for you"
      else onway0 += net;           // approved, clearing soon
    }
    const waiting = round2(earnings.filter(e => !e.received).reduce((s, e) => s + e.amount, 0));
    const gearAmt = gear(splits, period);
    const rechargeAmt = recharge(splits, period);
    // Gusto splits the NET check, so the tax is inside `gross` and in no bucket, and the
    // residual rule below renders money sent to the IRS as "On its way". Off the PAYOUT, never
    // account 2200: a system account with no profile_id, and a second source is a second
    // answer. sumWithheld dedupes the figure every split of one paycheck repeats.
    const taxAmt = sumWithheld(splits.filter(sp => sp.cleared_date && inPeriod(sp.cleared_date, period)));

    // Fees are read from the real source (each invoice's processing fee +
    // discount), NOT inferred as "whatever is left over". A residual must
    // never be silently relabeled as fees - that hid the entire gear bucket.
    const feeByInv = new Map();
    for (const i of invoices) {
      feeByInv.set(i.id, invoiceFees(i));
    }
    const seenInv = new Set();
    let fees = 0;
    for (const e of earnings) {
      if (!e.received || !e.invId || seenInv.has(e.invId)) continue;
      seenInv.add(e.invId);
      fees += feeByInv.get(e.invId) || 0;
    }
    fees = round2(fees);

    // Whatever the real buckets don't explain. Tiny (rounding) → fold into
    // landed silently. Material (>$1) → it is money earned but not yet
    // landed/sorted, so show it as "On its way" (truthful, visible), never
    // as fees. Negative (timing) → clamp; hero is always the sum of parts.
    const residual = round2(gross - (landed + taxAmt + held + onway0 + gearAmt + rechargeAmt + waiting + fees + inKind));
    let landedAdj = landed, onway = onway0;
    if (residual >= 1)        onway = round2(onway0 + residual);
    else if (residual > -1)   landedAdj = round2(landed + residual);
    const total = round2(landedAdj + taxAmt + held + onway + gearAmt + rechargeAmt + waiting + fees + inKind);

    return { total, landed: landedAdj, tax: taxAmt, held, onway, gear: gearAmt, recharge: rechargeAmt, waiting, fees, inKind };
  }, [periodLines, accountById, destMeta, earnings, splits, period, invoices]);

  const buckets = useMemo(() => {
    const b = [
      { key: 'landed',  label: 'Landed in your accounts', amount: recon.landed,
        sub: 'Paid out to your bank and savings.', color: SEG.landed },
      { key: 'held',    label: 'Held for you', amount: recon.held,
        sub: 'Yours. Parked in the business account for now so it stays above its minimum and avoids monthly bank fees. Comes to you later.', color: SEG.held },
      { key: 'onway',   label: 'On its way', amount: recon.onway,
        sub: 'Approved to pay you. Clearing into your accounts shortly.', color: SEG.onway },
      { key: 'gear',    label: 'Spent on your gear', amount: recon.gear,
        sub: 'Equipment and tools bought for you. You got the gear instead of cash.', color: SEG.gear },
      { key: 'recharge', label: 'Shared tools you covered', amount: recon.recharge,
        sub: 'Your share of subscriptions the business pays for you, like the apps that sync your stats. Came out of your payout instead of cash.', color: SEG.gear },
      { key: 'tax',     label: 'Taken out for tax', amount: recon.tax,
        sub: 'Income tax, sent to the government out of your pay before it reached your accounts.', color: SEG.tax },
      { key: 'waiting', label: 'Waiting on a brand', amount: recon.waiting,
        sub: 'A brand still owes this. It moves to your accounts once they pay.', color: SEG.waiting },
      { key: 'fees',    label: 'Billed but not banked', amount: recon.fees,   // invoiceFees() is the fee PLUS the discount, and a discount is a brand paying short, so this copy names the mechanism and never a cause
        sub: 'The gap between what was invoiced and what actually arrived. Fees along the way, and anything a brand paid short.', color: SEG.fees },
      { key: 'inkind',  label: 'Free product you got', amount: recon.inKind,
        sub: 'Brands sent products instead of cash. Still counts as money you earned.', color: SEG.fees, ghost: true },
    ];
    return b.filter(x => x.amount > 0.004);
  }, [recon]);

  const months = useMemo(() => {
    const dates = [
      ...lines.map(l => l.journal_entry?.entry_date).filter(Boolean),
      ...splits.map(s => s.cleared_date).filter(Boolean),
    ];
    return extractMonths(dates.map(d => ({ d })), 'd');
  }, [lines, splits]);

  const isEmpty = recon.total <= 0.004 && earnings.length === 0 && history.length === 0 && oopOutstanding <= 0;
  // The unfiltered twin, for when SHE narrows the period: money in other months is a
  // different fact from no money, and "Nothing here yet" is the wrong one to make the
  // loudest thing on a teen's own pay screen.
  const hasAnyMoney = lines.length > 0 || splits.length > 0;

  /**
   * Render the expandable detail under a bucket: the real events for event-backed
   * buckets (landed/gear/waiting/inkind) or a plain explanation for the derived
   * ones (onway/held/fees).
   */
  function bucketDetail(key) {
    if (key === 'landed') {
      const rows = history.filter(h => h.variant === 'cash');
      return rows.length
        ? rows.map(r => <DetailRow key={r.key} left={r.source || 'Payment'} hint={`to ${r.dest}`} right={fmtMoney(r.amount)} date={r.date} />)
        : <EmptyState variant="note" text="No payments cleared in this period." />;
    }
    if (key === 'onway') {
      return <p style={detailNote}>Approved to pay you and clearing into your accounts shortly. It will show under "Landed in your accounts" once it arrives.</p>;
    }
    if (key === 'held') {
      return <p style={detailNote}>This is set aside in the business account on purpose, so the balance never drops low enough to trigger monthly bank fees. It is still your money and reaches you later.</p>;
    }
    if (key === 'gear') {
      const rows = history.filter(h => h.variant === 'expense');
      return rows.length
        ? rows.map(r => <DetailRow key={r.key} left={r.expense} hint={r.source ? `from ${r.source}` : null} right={fmtMoney(r.amount)} date={r.date} />)
        : <EmptyState variant="note" text="No gear or costs covered in this period." />;
    }
    if (key === 'recharge') {
      const rows = history.filter(h => h.variant === 'recharge');
      return rows.length
        ? rows.map(r => <DetailRow key={r.key} left={r.expense} hint={r.source ? `from ${r.source}` : null} right={fmtMoney(r.amount)} date={r.date} />)
        : <EmptyState variant="note" text="No shared tools covered in this period." />;
    }
    if (key === 'tax') {
      return <p style={detailNote}>Payroll works out the tax on each payment and sends it to the government in your name. It still counts as money you made, which is why it is in the total above.</p>;
    }
    if (key === 'waiting') {
      const rows = earnings.filter(e => !e.received);
      return rows.length
        ? rows.map(r => <DetailRow key={r.key} left={r.label} hint="not paid yet" right={fmtMoney(r.amount)} date={r.date} />)
        : <EmptyState variant="note" text="Nothing waiting in this period." />;
    }
    if (key === 'fees') {
      return <p style={detailNote}>An invoice was written for one amount and a smaller amount arrived. The gap is fees charged along the way, or a brand paying less than it was billed. It still counts in your total above.</p>;
    }
    if (key === 'inkind') {
      const rows = history.filter(h => h.variant === 'inkind');
      return rows.length
        ? rows.map(r => <DetailRow key={r.key} left={r.source} hint="product, not cash" right={`~${fmtMoney(r.amount)}`} date={r.date} />)
        : <EmptyState variant="note" text="No product received in this period." />;
    }
    return null;
  }

  if (loading) return <SkeletonPage isMobile={isMobile} />;
  // Error before Empty: "Nothing here yet" is a claim about her pay.
  if (loadErr) {
    return (
      <div className="page">
        <Feedback value={loadErr} />
      </div>
    );
  }

  const heroSize = isMobile ? 'clamp(44px, 16vw, 60px)' : 78;
  const barH = isMobile ? 12 : 16;

  return (
    <div className="page">
      <div style={{ display: 'flex', alignItems: 'flex-end', justifyContent: 'space-between', gap: 16, flexWrap: 'wrap', marginBottom: isMobile ? 22 : 30 }}>
        <div>
          <h1 style={{ fontSize: 12, fontWeight: 400, letterSpacing: 3, textTransform: 'uppercase', color: 'var(--muted)', margin: 0, marginBottom: isMobile ? 4 : 8 }}>
            You made<HelpIcon slug="what-is-my-money" audience="creator" />
          </h1>
          <div style={{ fontFamily: 'var(--font-display)', fontSize: heroSize, lineHeight: 0.92, color: 'var(--white)', letterSpacing: 1,
                         opacity: mounted ? 1 : 0, transform: mounted ? 'none' : 'translateY(10px)',
                         transition: prefersReduced ? 'opacity .3s' : 'opacity .55s ease, transform .55s cubic-bezier(0.22,1,0.36,1)' }}>
            {fmtMoney(recon.total)}
          </div>
        </div>
        <PeriodSelect period={period} onChange={setPeriod} months={months} />
      </div>

      {isEmpty ? (
        /* Children: the heading is set in the display face at 22px, this screen's own voice
           rather than the shared 14px claim. "Show all time", not "Clear filters": the period
           is this page's only filter and this reader is a teen looking at her own pay. */
        <EmptyState style={{ padding: '56px 20px' }}
          filtered={{ unfiltered: hasAnyMoney, dirty: period !== 'all',
            onClear: () => setPeriod('all'), clearLabel: 'Show all time' }}>
          <div style={{ fontFamily: 'var(--font-display)', fontSize: 22, letterSpacing: 2, color: 'var(--white)', marginBottom: 6 }}>
            {hasAnyMoney ? 'Nothing in this month' : 'Nothing here yet'}
          </div>
          <div style={{ fontSize: 13, color: 'var(--muted)' }}>
            {hasAnyMoney
              ? 'Money moved in other months. Widen the date range to see it.'
              : 'No money has moved yet. Check with Patrick if something looks off.'}
          </div>
        </EmptyState>
      ) : (
        <>
          {/* Reconciliation bar: meaningful, not decorative. The list carries
              the numbers; the bar shows the shape at a glance. */}
          <div aria-hidden="true"
               style={{ display: 'flex', gap: 2, height: barH, borderRadius: 3, overflow: 'hidden', marginBottom: isMobile ? 22 : 28 }}>
            {buckets.map((b, i) => (
              <div key={b.key}
                   style={{
                     width: `${Math.max(0.8, (b.amount / recon.total) * 100)}%`,
                     minWidth: 3,
                     background: b.ghost ? INKIND_HATCH : b.color,
                     border: b.ghost ? '1px dashed rgba(255,140,66,0.45)' : 'none',
                     transformOrigin: 'left',
                     transform: mounted ? 'scaleX(1)' : 'scaleX(0)',
                     transition: prefersReduced ? 'none'
                       : `transform .6s cubic-bezier(0.22,1,0.36,1) ${0.1 + i * 0.06}s`,
                   }} />
            ))}
          </div>

          <div className="card" style={{ padding: isMobile ? 16 : '8px 24px' }}>
            {buckets.map((b, i) => {
              const open = openKey === b.key;
              const pct = Math.round((b.amount / recon.total) * 100);
              return (
                <div key={b.key}
                     style={{ borderBottom: i < buckets.length - 1 ? '1px solid var(--border)' : 'none',
                              opacity: mounted ? 1 : 0,
                              transform: mounted ? 'none' : 'translateY(8px)',
                              transition: prefersReduced ? 'opacity .3s' : `opacity .5s ease ${0.18 + i * 0.05}s, transform .5s ease ${0.18 + i * 0.05}s` }}>
                  <button
                    onClick={() => setOpenKey(open ? null : b.key)}
                    aria-expanded={open}
                    style={{ all: 'unset', boxSizing: 'border-box', width: '100%', cursor: 'pointer',
                             display: 'flex', alignItems: 'center', gap: 14, padding: isMobile ? '14px 0' : '16px 0' }}>
                    <span aria-hidden="true" style={{
                      width: 10, height: 10, borderRadius: 2, flexShrink: 0,
                      background: b.ghost ? 'transparent' : b.color,
                      backgroundImage: b.ghost ? INKIND_HATCH : 'none',
                      border: b.ghost ? '1px dashed rgba(255,140,66,0.55)' : 'none',
                    }} />
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{ display: 'flex', alignItems: 'baseline', gap: 8, flexWrap: 'wrap' }}>
                        <span style={{ color: 'var(--white)', fontWeight: 500, fontSize: isMobile ? 14 : 15 }}>{b.label}</span>
                        <span style={{ fontSize: 11, color: 'var(--dim)' }}>{pct}%</span>
                      </div>
                      <div style={{ fontSize: 12, color: 'var(--muted)', marginTop: 3, lineHeight: 1.45,
                                     maxWidth: 460, display: isMobile && !open ? '-webkit-box' : 'block',
                                     WebkitLineClamp: isMobile && !open ? 2 : 'unset', WebkitBoxOrient: 'vertical', overflow: 'hidden' }}>
                        {b.sub}
                      </div>
                    </div>
                    <div style={{ fontFamily: 'var(--font-display)', fontSize: isMobile ? 20 : 24, color: 'var(--white)',
                                   letterSpacing: 0.5, whiteSpace: 'nowrap', fontVariantNumeric: 'tabular-nums' }}>
                      {fmtMoney(b.amount)}
                    </div>
                    <ChevronIcon size={12} style={{ color: 'var(--dim)', flexShrink: 0,
                                   transform: open ? 'rotate(90deg)' : 'none', transition: 'transform .25s ease' }} />
                  </button>
                  <div style={{ display: 'grid', gridTemplateRows: open ? '1fr' : '0fr',
                                 transition: 'grid-template-rows .32s cubic-bezier(0.22,1,0.36,1)' }}>
                    <div style={{ overflow: 'hidden' }}>
                      <div style={{ padding: '2px 0 16px 24px' }}>{bucketDetail(b.key)}</div>
                    </div>
                  </div>
                </div>
              );
            })}

            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between',
                           gap: 12, padding: isMobile ? '16px 0 6px' : '18px 0 8px', marginTop: 4,
                           borderTop: '1px solid var(--border2)' }}>
              <span style={{ fontSize: 12, letterSpacing: 1.5, textTransform: 'uppercase', color: 'var(--green)' }}>
                Every dollar accounted for
              </span>
              <span style={{ fontFamily: 'var(--font-display)', fontSize: isMobile ? 20 : 24, color: 'var(--white)',
                             letterSpacing: 0.5, fontVariantNumeric: 'tabular-nums' }}>
                {fmtMoney(recon.total)}
              </span>
            </div>
          </div>

          {oopOutstanding > 0 && (
            <div style={{ display: 'flex', alignItems: 'flex-start', gap: 12, marginTop: 18, padding: isMobile ? '0 2px' : '0 4px' }}>
              <span aria-hidden="true" style={{ width: 10, height: 10, borderRadius: 2, marginTop: 5, flexShrink: 0,
                background: 'transparent', backgroundImage: INKIND_HATCH, border: '1px dashed rgba(255,140,66,0.55)' }} />
              <div>
                <span style={{ color: 'var(--white)', fontWeight: 500 }}>Coming back to you: {fmtMoney(oopOutstanding)}</span>
                <div style={{ fontSize: 12, color: 'var(--muted)', marginTop: 3, maxWidth: 460, lineHeight: 1.45 }}>
                  Money you spent from your own pocket on business stuff. It is added to your next payout.
                </div>
              </div>
            </div>
          )}

          {/* Calendar-year and ignores the period selector above: tax is annual. */}
          <CreatorTaxSetAside profileId={profileId} isMobile={isMobile} />

          <div style={{ marginTop: isMobile ? 26 : 34 }}>
            <Collapsible label="Every earning" count={earnings.length} open={earningsOpen} onToggle={() => setEarningsOpen(o => !o)}>
              {earnings.length === 0
                ? <EmptyState variant="note" text="No earnings in this period." />
                : earnings.map(e => (
                    <DetailRow key={e.key} left={e.label} hint={e.received ? 'paid' : 'waiting on the brand'} right={fmtMoney(e.amount)} date={e.date} />
                  ))}
            </Collapsible>
            <Collapsible label="Every payment" count={history.length} open={historyOpen} onToggle={() => setHistoryOpen(o => !o)}>
              {history.length === 0
                ? <EmptyState variant="note" text="No payments in this period." />
                : history.map(h => (
                    <DetailRow key={h.key}
                      left={h.variant === 'expense' ? h.expense : (h.source || 'Payment')}
                      hint={h.variant === 'cash' ? `to ${h.dest}` : h.variant === 'inkind' ? 'product, not cash' : (h.source ? `from ${h.source}` : 'business cost')}
                      right={(h.variant === 'inkind' ? '~' : '') + fmtMoney(h.amount)} date={h.date} />
                  ))}
            </Collapsible>
          </div>
        </>
      )}
    </div>
  );
}

// ── helpers ──────────────────────────────────────────────────────────────────

/**
 * Sum of in-period cleared expense splits = the "Spent on your gear" bucket.
 * @gotcha reads payout_splits directly because Pattern G credits 1000/6xxx, never
 *         a creator-owned ledger account, so gear never shows up in the line scan.
 * @see docs/MONEY.md Pattern G
 */
function gear(splits, period) {
  let s = 0;
  for (const sp of splits) {
    if (!sp.cleared_date || !sp.expense_id) continue;
    if (!inPeriod(sp.cleared_date, period)) continue;
    s += Number(sp.amount || 0);
  }
  return round2(s);
}

/**
 * Sum of in-period cleared recharge splits = the "Shared tools you covered"
 * bucket (Pattern R). Money the creator earned that went to cover their share of
 * a company-paid subscription instead of landing in their accounts.
 * @gotcha reads payout_splits directly: a recharge split posts no JE, so it never
 *         appears in the line scan. Gated on cleared_date so it is recognized at
 *         the same moment its sibling destination splits reduce "landed",
 *         symmetric with gear; otherwise the residual would mislabel it as
 *         "On its way".
 * @see docs/MONEY.md Pattern R
 */
function recharge(splits, period) {
  let s = 0;
  for (const sp of splits) {
    if (!sp.cleared_date || !sp.recharge_allocation_id) continue;
    if (!inPeriod(sp.cleared_date, period)) continue;
    s += Number(sp.amount || 0);
  }
  return round2(s);
}

const detailNote = { fontSize: 12.5, color: 'var(--muted)', lineHeight: 1.55, maxWidth: 520, margin: '4px 0 2px' };

function DetailRow({ left, hint, right, date }) {
  return (
    <div style={{ display: 'flex', alignItems: 'baseline', gap: 12, padding: '7px 0', fontSize: 13 }}>
      <div style={{ flex: 1, minWidth: 0 }}>
        <span title={left} style={{ color: 'var(--white)', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', display: 'inline-block', maxWidth: '100%' }}>{left}</span>
        {hint && <span style={{ color: 'var(--dim)', fontSize: 11, marginLeft: 8 }}>{hint}</span>}
      </div>
      {date && <span style={{ color: 'var(--dim)', fontSize: 11, whiteSpace: 'nowrap' }}>{fmtDate(date)}</span>}
      <span style={{ color: 'var(--white)', fontVariantNumeric: 'tabular-nums', whiteSpace: 'nowrap', minWidth: 78, textAlign: 'right' }}>{right}</span>
    </div>
  );
}

function Collapsible({ label, count, open, onToggle, children }) {
  return (
    <div style={{ borderTop: '1px solid var(--border)' }}>
      <button onClick={onToggle} aria-expanded={open}
        style={{ all: 'unset', boxSizing: 'border-box', width: '100%', cursor: 'pointer',
                 display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '14px 0' }}>
        <span style={{ fontFamily: 'var(--font-display)', letterSpacing: 2.5, fontSize: 15, color: 'var(--white)' }}>
          {label} <span style={{ color: 'var(--muted)', fontSize: 12, fontFamily: 'var(--font-body)', letterSpacing: 0, marginLeft: 6 }}>({count})</span>
        </span>
        <ChevronIcon size={12} style={{ color: 'var(--dim)', transform: open ? 'rotate(90deg)' : 'none', transition: 'transform .25s ease' }} />
      </button>
      <div style={{ display: 'grid', gridTemplateRows: open ? '1fr' : '0fr', transition: 'grid-template-rows .32s cubic-bezier(0.22,1,0.36,1)' }}>
        <div style={{ overflow: 'hidden' }}>
          <div style={{ padding: '0 0 16px' }}>{children}</div>
        </div>
      </div>
    </div>
  );
}

function SkeletonPage({ isMobile }) {
  const bar = (w, h, mb) => (
    <div style={{ width: w, height: h, marginBottom: mb, borderRadius: 4,
      background: 'var(--surface2)', animation: 'pulse 1.4s ease-in-out infinite' }} />
  );
  return (
    <div className="page">
      {bar(110, 12, 10)}
      {bar(isMobile ? 220 : 320, isMobile ? 48 : 70, 26)}
      {bar('100%', isMobile ? 12 : 16, 26)}
      <div className="card" style={{ padding: isMobile ? 16 : '8px 24px' }}>
        {[0, 1, 2, 3, 4].map(i => (
          <div key={i} style={{ display: 'flex', alignItems: 'center', gap: 14, padding: '16px 0',
                                 borderBottom: i < 4 ? '1px solid var(--border)' : 'none' }}>
            <div style={{ flex: 1 }}>{bar('45%', 14, 8)}{bar('70%', 11, 0)}</div>
            {bar(90, 22, 0)}
          </div>
        ))}
      </div>
    </div>
  );
}
