/**
 * pages/CreatorDashboard.js - desktop creator shell + view router.
 *
 * The desktop creator experience (mobile creators get MobilePostPage from App.js
 * instead). Sidebar-driven like the admin shell, but routing differs: Campaigns
 * stays ALWAYS mounted (display:block/none) so its deep panel state and pending
 * navigation props survive view switches, while every other view is conditionally
 * rendered (mounted only when active). Active view persists to localStorage.
 *
 * @gotcha do not move Campaigns into the conditional block; unmounting it drops
 *         open-panel state and the pendingCampaignId/pendingDeliverableId handoff.
 * @see docs/CODEBASE.md (routing)
 */
import React, { useState, useEffect, useCallback } from 'react';
import Sidebar from '../components/shared/Sidebar';
import { useHelpOpen } from '../hooks/useHelpOpen';
import { AudienceProvider } from '../contexts/AudienceContext';
import CreatorOverview from '../components/creator/CreatorOverview';
import CreatorCampaigns from '../components/creator/CreatorCampaigns';
import CreatorAnalytics from '../components/creator/CreatorAnalytics';
import CreatorPayments from '../components/creator/CreatorPayments';
import CreatorRewards from '../components/creator/CreatorRewards';
import CreatorMyMoney from '../components/creator/CreatorMyMoney';
import CreatorCalendar from '../components/creator/CreatorCalendar';
import CreatorSharedDashboards from '../components/creator/CreatorSharedDashboards';
import CreatorExpenses from '../components/creator/CreatorExpenses';
import CreatorHelp from '../components/creator/CreatorHelp';
import SecurityPage from '../components/shared/SecurityPage';
import ErrorBoundary from '../components/shared/ErrorBoundary';
import { IC } from './navIcons';
import { hasUnsaved, DISCARD_PROMPT } from '../hooks/useUnsavedGuard';
import { useConfirm } from '../components/shared/ConfirmDialog';

const NAV = [
  {
    label: null,
    items: [
      { view: 'overview',  icon: IC.home,     label: 'My Overview' },
      { view: 'campaigns', icon: IC.campaign,  label: 'My Campaigns' },
      { view: 'calendar',  icon: IC.calendar,  label: 'My Calendar' },
      { view: 'payments',  icon: IC.dollar,    label: 'My Payments' },
      { view: 'expenses',  icon: IC.receipt,   label: 'My Expenses' },
      { view: 'rewards',   icon: IC.star,      label: 'My Rewards' },
      { view: 'money',     icon: IC.dollar,    label: 'My Money' },
      { view: 'analytics',         icon: IC.chart,  label: 'My Analytics' },
      { view: 'shared-dashboards', icon: IC.share,   label: 'Shared Dashboards' },
    ]
  },
  {
    label: 'Account',
    items: [
      { view: 'security', icon: IC.shield, label: 'Security' },
    ]
  },
  {
    label: 'Help',
    items: [
      { view: 'help', icon: IC.help, label: 'Help' },
    ]
  }
];

const CREATOR_VIEW_KEY = 'nys_creator_active_view';

/** The desktop creator sidebar + routed-content shell. */
export default function CreatorDashboard() {
  const [activeView, setActiveView] = useState(() => {
    try { return localStorage.getItem(CREATOR_VIEW_KEY) || 'overview'; }
    catch { return 'overview'; }
  });
  useEffect(() => {
    try { localStorage.setItem(CREATOR_VIEW_KEY, activeView); } catch {}
  }, [activeView]);

  const confirm = useConfirm();
  /**
   * Switching view unmounts whatever is on screen, and a detail panel has no close button of
   * its own, so navigating IS how a half-filled panel gets discarded. Everything else in the
   * hub leaves through Modal, which asks for itself.
   */
  const goToView = useCallback(async (next) => {
    if (hasUnsaved() && !(await confirm(DISCARD_PROMPT))) return;
    setActiveView(next);
  }, [confirm]);
  const [pendingCampaignId, setPendingCampaignId]       = useState(null);
  const [pendingDeliverableId, setPendingDeliverableId] = useState(null);
  const [refreshKey, setRefreshKey] = useState(0);
  const [pendingHelpSlug, setPendingHelpSlug] = useState(null);
  const [helpReturnView,  setHelpReturnView]  = useState(null);

  useHelpOpen({
    audience: 'creator', nav: NAV, setActiveView, setHelpReturnView, setPendingHelpSlug,
  });

  function backFromHelp() {
    if (!helpReturnView) return;
    const target = helpReturnView.view;
    setHelpReturnView(null);
    setPendingHelpSlug(null);
    setActiveView(target);
  }

  function navigateToCampaign(campaignId) {
    setPendingCampaignId(campaignId);
    setPendingDeliverableId(null);
    setActiveView('campaigns');
  }

  function navigateToDeliverable(campaignId, deliverableId) {
    setPendingCampaignId(campaignId);
    setPendingDeliverableId(deliverableId);
    setActiveView('campaigns');
  }

  function triggerRefresh() {
    setRefreshKey(k => k + 1);
  }

  return (
    <AudienceProvider audience="creator">
    <div className="app-layout">
      <Sidebar navItems={NAV} activeView={activeView} setActiveView={goToView} />
      <main className="main-content" id="main-content">
        {/* Campaigns stays always-mounted so deep panel state and pending navigation props are preserved */}
        <div style={{ display: activeView === 'campaigns' ? 'block' : 'none' }}>
          <ErrorBoundary sectionName="Campaigns">
            <CreatorCampaigns
              pendingCampaignId={pendingCampaignId}
              pendingDeliverableId={pendingDeliverableId}
              onCampaignStatusChanged={triggerRefresh}
            />
          </ErrorBoundary>
        </div>
        {activeView === 'overview' && (
          <ErrorBoundary sectionName="Overview"><CreatorOverview setActiveView={setActiveView} navigateToCampaign={navigateToCampaign} navigateToDeliverable={navigateToDeliverable} refreshKey={refreshKey} /></ErrorBoundary>
        )}
        {activeView === 'calendar' && (
          <ErrorBoundary sectionName="Calendar"><CreatorCalendar /></ErrorBoundary>
        )}
        {activeView === 'payments' && (
          <ErrorBoundary sectionName="Payments"><CreatorPayments /></ErrorBoundary>
        )}
        {activeView === 'expenses' && (
          <ErrorBoundary sectionName="Expenses"><CreatorExpenses /></ErrorBoundary>
        )}
        {activeView === 'rewards' && (
          <ErrorBoundary sectionName="Rewards"><CreatorRewards /></ErrorBoundary>
        )}
        {activeView === 'money' && (
          <ErrorBoundary sectionName="My Money"><CreatorMyMoney /></ErrorBoundary>
        )}
        {activeView === 'analytics' && (
          <ErrorBoundary sectionName="Analytics"><CreatorAnalytics navigateToCampaign={navigateToCampaign} /></ErrorBoundary>
        )}
        {activeView === 'shared-dashboards' && (
          <ErrorBoundary sectionName="Shared Dashboards"><CreatorSharedDashboards /></ErrorBoundary>
        )}
        {activeView === 'security' && (
          <ErrorBoundary sectionName="Security"><SecurityPage /></ErrorBoundary>
        )}
        {activeView === 'help' && (
          <ErrorBoundary sectionName="Help"><CreatorHelp initialSlug={pendingHelpSlug} returnView={helpReturnView} onBack={backFromHelp} /></ErrorBoundary>
        )}
      </main>
    </div>
    </AudienceProvider>
  );
}
