import React from 'react';
import { useAuth } from '../../hooks/useAuth';
import CalendarPage from '../shared/CalendarPage';

/**
 * components/creator/CreatorCalendar.js - thin creator wrapper around
 * components/shared/CalendarPage; passes isAdmin=false + the creator's profile id.
 *
 * A deliberate pass-through stub, not an unfinished component. @see docs/CODEBASE.md
 */
export default function CreatorCalendar() {
  const { profile } = useAuth();
  return <CalendarPage isAdmin={false} profileId={profile?.id} />;
}
